import{_ as a,a0 as r,w as l,s as p,ao as d,I as n,x as t,a1 as i,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何重置 RHEL7/CentOS7 系統的密碼 | LCTT x X-CMD","titleTemplate":false,"description":"如何重置 RHEL7/CentOS7 系統的密碼 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何重置 RHEL7/CentOS7 系統的密碼 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何重置 RHEL7/CentOS7 系統的密碼 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20160908 How to reset the root password in RHEL7CentOS7Scientific Linux 7- based systems","title":"如何重置 RHEL7/CentOS7 系統的密碼","tag":"201702","desc":""},"relativePath":"201702/20160908 How to reset the root password in RHEL7CentOS7Scientific Linux 7- based systems.md","filePath":"[post].md"}'),h={name:"201702/20160908 How to reset the root password in RHEL7CentOS7Scientific Linux 7- based systems.md"};function g(c,s,u,k,b,f){const e=r("Link");return l(),p("div",null,[s[13]||(s[13]=d('<h1 id="如何重置-rhel7-centos7-系統的密碼" tabindex="-1">如何重置 RHEL7/CentOS7 系統的密碼 <a class="header-anchor" href="#如何重置-rhel7-centos7-系統的密碼" aria-label="Permalink to “如何重置 RHEL7/CentOS7 系統的密碼”">​</a></h1><h3 id="介紹" tabindex="-1">介紹 <a class="header-anchor" href="#介紹" aria-label="Permalink to “介紹”">​</a></h3><p><strong>目的</strong></p><p>在 RHEL7/CentOS7/Scientific Linux 7 中重設 root 密碼。</p><p><strong>要求</strong></p><p>RHEL7 / CentOS7 / Scientific Linux 7</p><p><strong>困難程度</strong></p><p>中等</p><h3 id="指導" tabindex="-1">指導 <a class="header-anchor" href="#指導" aria-label="Permalink to “指導”">​</a></h3><p>RHEL7 的世界發生了變化，重置 root 密碼的方式也一樣。雖然中斷引導過程的舊方法（init=/bin/bash）仍然有效，但它不再是推薦的。“Systemd” 使用 “rd.break” 來中斷引導。讓我們快速瀏覽下整個過程。</p><p><strong>啓動進入最小模式</strong></p><p>重啓系統並在內核列表頁面在系統啓動之前按下 <code>e</code>。你會進入編輯模式。</p><p><strong>中斷啓動進程</strong></p><p>在內核字符串中 - 在以 <code>linux 16 /vmlinuz- ect</code> 結尾的行中輸入 <code>rd.break</code>。接着 <code>Ctrl+X</code> 重啓。系統啓動進入初始化內存磁盤，並掛載在 <code>/sysroot</code>。在此模式中你不需要輸入密碼。</p><p><strong>重新掛載文件系統以便讀寫</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>switch_root:/# mount -o remount,rw /sysroot/</span></span></code></pre></div><p><strong>使 /sysroot 成為根目錄</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>switch_root:/# chroot /sysroot</span></span></code></pre></div><p>命令列提示符會稍微改變。</p><p><strong>修改 root 密碼</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sh-4.2# passwd</span></span></code></pre></div><p><strong>加載 SELinux 策略</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sh-4.2# load_policy -i</span></span></code></pre></div><p><strong>在 /etc/shadow 中設置上下文類型</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sh-4.2# chcon -t shadow_t /etc/shadow</span></span></code></pre></div><p>注意：你可以通過如下創建 <code>autorelabel</code> 文件的方式來略過最後兩步，但自動重建卷標會花費很長時間。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sh-4.2# touch /.autorelabel</span></span></code></pre></div><p>因為這個原因，儘管它更簡單，它應該作為“懶人選擇”，而不是建議。</p><p><strong>退出並重啓</strong></p><p>退出並重啓並用新的 root 密碼登錄。</p><hr>',31)),n("p",null,[s[1]||(s[1]=t("via: ",-1)),i(e,{href:"https://linuxconfig.org/how-to-reset-the-root-password-in-rhel7-centos7-scientific-linux-7-based-systems"},{default:o(()=>[...s[0]||(s[0]=[t("https://linuxconfig.org/how-to-reset-the-root-password-in-rhel7-centos7-scientific-linux-7-based-systems",-1)])]),_:1})]),n("p",null,[s[5]||(s[5]=t("作者：",-1)),i(e,{href:"https://linuxconfig.org/how-to-reset-the-root-password-in-rhel7-centos7-scientific-linux-7-based-systems"},{default:o(()=>[...s[2]||(s[2]=[t("Rado Folwarczny",-1)])]),_:1}),s[6]||(s[6]=t(" 譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:o(()=>[...s[3]||(s[3]=[t("geekpi",-1)])]),_:1}),s[7]||(s[7]=t(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:o(()=>[...s[4]||(s[4]=[t("wxy",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=t("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[8]||(s[8]=[t("LCTT",-1)])]),_:1}),s[11]||(s[11]=t(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:o(()=>[...s[9]||(s[9]=[t("Linux中國",-1)])]),_:1}),s[12]||(s[12]=t(" 榮譽推出",-1))])])}const y=a(h,[["render",g]]);export{x as __pageData,y as default};
